function loadgrafik(dss_url){
	$.ajax({
      headers: {
        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
      },
      type:"get",
      url: base_url+"grafik/get_data/"+dss_url,
      dataType:"json",

      complete: function () {
      },
      success:function(result)
      {
        // console.log(result);
      	Highcharts.chart('grafik', {
			    chart : {
			      type:"line"
			    },
			    title : {
			      text : '',
			      align : 'center'

			    },
			    subtitle : {
			      text : 'Tren Tahunan',
			      align : 'center'
			    },
			    yAxis : {
			      title : {
			        text : 'Jumlah'
			      }
			    },
			    xAxis : {
			      categories : result['tahuns']
			    },
			    series : result['result']
			  });
        

        if (dss_url !== null) {
          $('#tahun_usul').html(result.tahuns[0]);
        }
      },
      error:function(){
        alert('Gagal menampilkan tabel...');
      }
  });
}